pub fn take<Q: ?Sized>(&mut self, value: &Q) -> Option<T>
where
    T: Borrow<Q>,
    Q: Ord,
{
    if self.contains(value) {
        self.tree.remove(value).map(|_| value.borrow().to_owned())
    } else {
        None
    }
}

